custom_overrides:
#page-workspaces {
    background-color: #ffbc38;
    
}
.widget {
    border-radius: 8px;
    padding: 10px;
    margin: 5px;
    text-align: center;
    border: 1px solid black;
}

.widget.shortcut-widget-box {
    background-color: #e0e0e0;
    cursor: pointer;
}
.btn-primary {
    background: #0575E6;  /* fallback for old browsers */
    background: -webkit-linear-gradient(to right, #021B79, #0575E6);  /* Chrome 10-25, Safari 5.1-6 */
    background: linear-gradient(to right, #021B79, #0575E6); /* W3C, IE 10+/ Edge, Firefox 16+, Chrome 26+, Opera 12+, Safari 7+ */
    color:white;

}

theme_scss:
@import url("https://fonts.googleapis.com/css2?family=cairo:wght:400;500;600;700;800&display=swap");
// backward compatibility. deprecated in v15
$font-family-sans-serif: "cairo", "InterVariable", "Inter", -apple-system, BlinkMacSystemFont,
	"Segoe UI", "Roboto", "Oxygen", "Ubuntu", "Cantarell", "Fira Sans",
	"Droid Sans", "Helvetica Neue", sans-serif;

// override font stack if custom font is set in website theme
:root {
	--font-stack: "cairo", "InterVariable", "Inter", -apple-system, BlinkMacSystemFont,
	"Segoe UI", "Roboto", "Oxygen", "Ubuntu", "Cantarell", "Fira Sans",
	"Droid Sans", "Helvetica Neue", sans-serif !important;
}
$enable-shadows: true;
$enable-gradients: true;
$enable-rounded: true;

